class Solution {
    public int eliminateMaximum(int[] dist,int[] speed){
        int[] arrival=new int[dist.length];
        for(int i=0;i<dist.length;i++)arrival[i]=(dist[i]+speed[i]-1)/speed[i];
        Arrays.sort(arrival);
        for(int i=0;i<arrival.length;i++)if(arrival[i]<=i)return i;
        return arrival.length;
    }
}

code.kotlin:
class Solution {
    fun eliminateMaximum(dist:IntArray,speed:IntArray):Int{
        val arrival=IntArray(dist.size){
            (dist[it]+speed[it]-1)/speed[it]
        };
        arrival.sort();
        for(i in arrival.indices)if(arrival[i]<=i)return i;
        return arrival.size
    }
}

code.cpp:
class Solution {
    public: int eliminateMaximum(vector<int>& dist,vector<int>& speed){
        vector<int> arrival(dist.size());
        for(int i=0;i<(int)dist.size();++i)arrival[i]=(dist[i]+speed[i]-1)/speed[i];
        sort(arrival.begin(),arrival.end());
        for(int i=0;i<(int)arrival.size();++i)if(arrival[i]<=i)return i;
        return arrival.size();
    }
};
